python3 - <<'PY'
import subprocess, re
branches=["rachel","monica","phoebe","joey","chandler","ross"]
commits=[]
for b in branches:
    out=subprocess.check_output(["git","-C","/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill","rev-list","origin/friend/"+b], text=True)
    for sha in out.split():
        body=subprocess.check_output(["git","-C","/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill","show","-s","--format=%B",sha], text=True)
        if "Friend-Message: 1" not in body: continue
        m_ep=re.search(r'^Episode: (.+)$', body, re.M)
        if not m_ep: continue
        commits.append((b,sha,m_ep.group(1).strip()))
src=set()
import glob
base="/home/runner/work/beetle-in-the-anthill/wt-main"
for path in glob.glob(base+"/S*/*.md"):
    for line in open(path):
        m=re.match(r'^Source: friend/(\w+) @ ([0-9a-f]{40})$', line.strip())
        if m: src.add(m.group(2))
for b,sha,ep in commits:
    if sha not in src:
        print(ep,b,sha)
